mapper.select:
SELECT id AS id, cfg_output_id AS cfgOutputId, next_level_id AS nextLevelId, start_time AS startTime, end_time AS endTime, status AS status, create_time AS createTime, update_time AS updateTime, create_user_name AS createUserName, create_user_id AS createUserId, update_user_name AS updateUserName, update_user_id AS updateUserId, version AS version, is_deleted AS isDeleted, task_type AS taskType, error_count AS errorCount, input_task_id AS inputTaskId, exec_timeout AS execTimeout, error_message AS errorMessage, exec_system AS execSystem, instance_id AS instanceId from dmp_output_task where ${params.sqlMap.default} and is_deleted = false
${params.permissionSql}
order by update_time desc

SELECT CASE WHEN status IN ('init', 'fds', 'mongo', 'dmp') THEN 'waitFinish' WHEN status = 'error' THEN 'error' WHEN status = 'finish' THEN 'finish' ELSE status END AS tabFlag, CASE WHEN status IN ('init', 'fds', 'mongo', 'dmp') THEN '待完成' WHEN status = 'error' THEN '异常' WHEN status = 'finish' THEN '完成' ELSE status END AS tabFlagName, COUNT(*) AS count FROM dmp_output_task WHERE is_deleted = FALSE
${params.permissionSql}
GROUP BY tabFlag, tabFlagName
